<?php if (!defined('ABSPATH')) exit; ?><template id="tranter-event-<?php echo esc_attr($e['id']); ?>"><div class="tranter-modal-event"><?php if($e['image']): ?><img class="tranter-modal-image" src="<?php echo esc_url($e['image']); ?>" alt="<?php echo esc_attr($e['title']); ?>"><?php endif; ?><span class="tranter-card-meta"><?php echo esc_html($e['type']); ?> · <?php echo esc_html($e['date']); ?> <?php echo esc_html($e['time']); ?></span><h2><?php echo esc_html($e['title']); ?></h2><?php if($e['partner']): ?><p class="tranter-modal-partner">In partnership with <?php echo esc_html($e['partner']['name']); ?><?php if($e['partner']['logo']): ?><img src="<?php echo esc_url($e['partner']['logo']); ?>" alt=""><?php endif; ?></p><?php endif; ?><p class="tranter-modal-location"><?php echo esc_html($e['location']); ?><?php if($e['location_url']): ?> · <a href="<?php echo esc_url($e['location_url']); ?>" target="_blank" rel="noopener">View map</a><?php endif; ?></p><div class="tranter-modal-description"><?php echo wp_kses_post($e['description']); ?></div><div class="tranter-modal-actions"><?php if($e['registration_enabled']&&$e['registration_url']): ?><a class="tranter-button" href="<?php echo esc_url($e['registration_url']); ?>" target="_blank" rel="noopener"><?php echo esc_html($e['registration_text']); ?></a><?php endif; ?><?php if($e['landing_enabled']&&$e['landing_url']): ?><a class="tranter-button tranter-button-outline" href="<?php echo esc_url($e['landing_url']); ?>">Dedicated event page</a><?php endif; ?></div><?php if($e['gallery']): ?><div class="tranter-modal-gallery"><?php foreach($e['gallery'] as $img): ?><img src="<?php echo esc_url($img); ?>" alt="" loading="lazy"><?php endforeach; ?></div><?php endif; ?></div></template>
